-- Seed: Regelwerk (migriert aus bloodline.cc)

INSERT INTO laws (slug, title, category, html, text, word_count, ref_count, position, updated_at, updated_by) VALUES ('allgemeine-regeln-grundregeln', 'Grundregeln', 'Allgemeine Regeln', '<h3>§1.0 · Altersbeschränkung</h3>
<p>Das Spielen auf dem Roleplay-Server ist ab 16 Jahren gestattet. In Ausnahmefällen kann dies auch ab dem 15. Lebensjahr erlaubt sein, sofern eine angemessene Reife nachgewiesen wird.</p>
<h3>§2.0 · Regelkonformes Verhalten</h3>
<p>Das aktive Suchen und Ausnutzen von Grauzonen im Regelwerk ist verboten.</p>
<h3>§3.0 · Werbung für externe GTA V-Projekte</h3>
<p>Es ist untersagt, für externe GTA V-Projekte auf Plattformen von Bloodline zu werben.</p>
<h3>§4.0 · Verkauf und Handel von Spielerkonten und In-Game-Gegenständen</h3>
<p>Der Verkauf und Handel von Spielerkonten, Gegenständen und Währungen aus dem Spiel gegen externe Gegenstände und Währungen ist verboten.</p>
<h3>§5.0 · Spielumgebung</h3>
<p>Das Roleplay (RP) findet in Los Santos statt.</p>
<h3>§6.0 · Midcore Server</h3>
<p>Wir sind ein Midcore-Server und legen besonderen Wert auf die Einhaltung unserer Regeln.</p>', '§1.0 Altersbeschränkung Das Spielen auf dem Roleplay-Server ist ab 16 Jahren gestattet. In Ausnahmefällen kann dies auch ab dem 15. Lebensjahr erlaubt sein, sofern eine angemessene Reife nachgewiesen wird. §2.0 Regelkonformes Verhalten Das aktive Suchen und Ausnutzen von Grauzonen im Regelwerk ist verboten. §3.0 Werbung für externe GTA V-Projekte Es ist untersagt, für externe GTA V-Projekte auf Plattformen von Bloodline zu werben. §4.0 Verkauf und Handel von Spielerkonten und In-Game-Gegenständen Der Verkauf und Handel von Spielerkonten, Gegenständen und Währungen aus dem Spiel gegen externe Gegenstände und Währungen ist verboten. §5.0 Spielumgebung Das Roleplay (RP) findet in Los Santos statt. §6.0 Midcore Server Wir sind ein Midcore-Server und legen besonderen Wert auf die Einhaltung unserer Regeln.', 115, 0, 1, 1777593600000, 'migration');
INSERT INTO laws (slug, title, category, html, text, word_count, ref_count, position, updated_at, updated_by) VALUES ('allgemeine-regeln-roleplay-grundsaetze', 'Roleplay Grundsätze', 'Allgemeine Regeln', '<h3>§1.0 · Priorität der Charaktergesundheit</h3>
<p>Die Gesundheit und das Überleben deines Charakters stehen stets an erster Stelle und sollten in jeder Roleplay-Situation berücksichtigt werden.</p>
<h3>§2.0 · Beachtung des sozialen Status</h3>
<p>Sei dir bewusst über deinen sozialen Status und handle entsprechend.</p>
<h3>§3.0 · Abbruch bei persönlichem Unwohlsein</h3>
<p>Falls eine Person sich aufgrund einer Roleplay-Situation extrem moralisch oder persönlich angegriffen fühlt, muss die Situation beendet werden.</p>
<h3>§4.0 · Mitteilung bei technischen Problemen</h3>
<p>Spieler, die aufgrund technischer Probleme eine Roleplay-Situation vorzeitig verlassen müssen, sind verpflichtet, die beteiligten Spieler über Discord über ihren Ausfall zu informieren. Ist dies nicht möglich, muss der Support kontaktiert werden.</p>
<h3>§5.0 · Verbot der Ausnutzung technischer Probleme</h3>
<p>Das Ausnutzen von technischen Problemen anderer Mitspieler ist untersagt.</p>
<h3>§6.0 · Diebstahl staatlicher Fahrzeuge</h3>
<p>Staatliche Fahrzeuge dürfen nicht gestohlen werden, es sei denn, es liegt ein RP Strang/Sinn vor.</p>', '§1.0 Priorität der Charaktergesundheit Die Gesundheit und das Überleben deines Charakters stehen stets an erster Stelle und sollten in jeder Roleplay-Situation berücksichtigt werden. §2.0 Beachtung des sozialen Status Sei dir bewusst über deinen sozialen Status und handle entsprechend. §3.0 Abbruch bei persönlichem Unwohlsein Falls eine Person sich aufgrund einer Roleplay-Situation extrem moralisch oder persönlich angegriffen fühlt, muss die Situation beendet werden. §4.0 Mitteilung bei technischen Problemen Spieler, die aufgrund technischer Probleme eine Roleplay-Situation vorzeitig verlassen müssen, sind verpflichtet, die beteiligten Spieler über Discord über ihren Ausfall zu informieren. Ist dies nicht möglich, muss der Support kontaktiert werden. §5.0 Verbot der Ausnutzung technischer Probleme Das Ausnutzen von technischen Problemen anderer Mitspieler ist untersagt. §6.0 Diebstahl staatlicher Fahrzeuge Staatliche Fahrzeuge dürfen nicht gestohlen werden, es sei denn, es liegt ein RP Strang/Sinn vor.', 131, 0, 2, 1777593600000, 'migration');
INSERT INTO laws (slug, title, category, html, text, word_count, ref_count, position, updated_at, updated_by) VALUES ('roleplay-regeln-random-deathmatch-rdm', 'Random Deathmatch (RDM)', 'Roleplay Regeln', '<h3>§1.0 · Gewalt gegen andere Spieler ohne berechtigten Grund ist nicht erlaubt</h3>
<p>Es ist nicht gestattet, andere Spieler zu töten, zu beschießen oder anzugreifen, es sei denn, es gibt einen nachvollziehbaren Grund dafür.</p>', '§1.0 Gewalt gegen andere Spieler ohne berechtigten Grund ist nicht erlaubt Es ist nicht gestattet, andere Spieler zu töten, zu beschießen oder anzugreifen, es sei denn, es gibt einen nachvollziehbaren Grund dafür.', 32, 0, 3, 1777593600000, 'migration');
INSERT INTO laws (slug, title, category, html, text, word_count, ref_count, position, updated_at, updated_by) VALUES ('roleplay-regeln-vehicle-deathmatch-vdm', 'Vehicle Deathmatch (VDM)', 'Roleplay Regeln', '<h3>§1.0 · Kein Töten, Anfahren oder Angreifen von Spielern mit Fahrzeugen</h3>
<p>Es ist grundsätzlich untersagt, andere Spieler zu töten, anzufahren oder anzugreifen, insbesondere unter Verwendung von Fahrzeugen.</p>', '§1.0 Kein Töten, Anfahren oder Angreifen von Spielern mit Fahrzeugen Es ist grundsätzlich untersagt, andere Spieler zu töten, anzufahren oder anzugreifen, insbesondere unter Verwendung von Fahrzeugen.', 26, 0, 4, 1777593600000, 'migration');
INSERT INTO laws (slug, title, category, html, text, word_count, ref_count, position, updated_at, updated_by) VALUES ('roleplay-regeln-power-rp', 'Power RP', 'Roleplay Regeln', '<h3>§1.0 · Power RP: Respekt für die Spielhandlung des Anderen</h3>
<p>Power RP bedeutet, einem anderen Spieler nicht die Möglichkeit zu geben, auf die eigene Spielhandlung zu reagieren, oder ihm sein Rollenspiel aufzuzwingen, ohne Raum für Handlungen zu lassen.</p>
<h3>§2.0 · Zwanghafte Geldautomatenauszahlungen sind nicht gestattet</h3>
<p>Es ist unangemessen, andere Spieler zur Auszahlung an Geldautomaten zu zwingen.</p>', '§1.0 Power RP: Respekt für die Spielhandlung des Anderen Power RP bedeutet, einem anderen Spieler nicht die Möglichkeit zu geben, auf die eigene Spielhandlung zu reagieren, oder ihm sein Rollenspiel aufzuzwingen, ohne Raum für Handlungen zu lassen. §2.0 Zwanghafte Geldautomatenauszahlungen sind nicht gestattet Es ist unangemessen, andere Spieler zur Auszahlung an Geldautomaten zu zwingen.', 54, 0, 5, 1777593600000, 'migration');
INSERT INTO laws (slug, title, category, html, text, word_count, ref_count, position, updated_at, updated_by) VALUES ('roleplay-regeln-scripted-rp', 'Scripted RP', 'Roleplay Regeln', '<h3>§1.0 · Absprachen über den Verlauf von RP-Situationen</h3>
<p>Es ist untersagt, im Voraus mit den beteiligten Parteien außerhalb des Spiels über den Verlauf oder das Ergebnis von RP-Situationen oder Handlungssträngen zu kommunizieren.</p>', '§1.0 Absprachen über den Verlauf von RP-Situationen Es ist untersagt, im Voraus mit den beteiligten Parteien außerhalb des Spiels über den Verlauf oder das Ergebnis von RP-Situationen oder Handlungssträngen zu kommunizieren.', 31, 0, 6, 1777593600000, 'migration');
INSERT INTO laws (slug, title, category, html, text, word_count, ref_count, position, updated_at, updated_by) VALUES ('roleplay-regeln-dritt-partei', 'Dritt Partei', 'Roleplay Regeln', '<h3>§1.0 · Dritt Partei: Einmischen ohne Zusammenhang im Roleplay</h3>
<p>Unter Dritt Partei versteht man das Einmischen in eine Roleplaysituation, ohne einen direkten Bezug dazu zu haben.</p>', '§1.0 Dritt Partei: Einmischen ohne Zusammenhang im Roleplay Unter Dritt Partei versteht man das Einmischen in eine Roleplaysituation, ohne einen direkten Bezug dazu zu haben.', 25, 0, 7, 1777593600000, 'migration');
INSERT INTO laws (slug, title, category, html, text, word_count, ref_count, position, updated_at, updated_by) VALUES ('roleplay-regeln-fail-rp', 'Fail RP', 'Roleplay Regeln', '<h3>§1.0 · Fail RP - Rollenspielrealismus wahren</h3>
<p>Das Verlassen der Rolle im Rollenspiel oder das unangemessene Ausführen einer RP-Situation wird als "Fail RP" bezeichnet. Es ist wichtig, sich stets zu fragen, ob die Aktion, die man ausführt, realistisch für den eigenen Charakter ist.</p>
<h3>§2.0 · Fahrzeugnutzung im Gebirge</h3>
<p>Fahrzeuge, die tiefergelegt sind oder offenkundig nicht für Offroad-Fahrten geeignet sind, dürfen im Gebirge nicht verwendet werden. Eine Ausnahme bilden lediglich Nutzfahrzeuge, wie Kleintransporter (z.B. Burrito, Youga, etc.), während LKW ausgeschlossen sind.</p>
<h3>§3.0 · Fahrzeugnutzung mit Platten</h3>
<p>Fahrzeugnutzung mit Platten ist in bestimmten Fällen stark eingeschränkt. Wenn ein PKW zwei Platten hat, ist es nicht gestattet, weiterzufahren. In solchen Situationen sollte das Fahrzeug abgestellt und repariert werden, bevor die Fahrt fortgesetzt wird.</p>', '§1.0 Fail RP - Rollenspielrealismus wahren Das Verlassen der Rolle im Rollenspiel oder das unangemessene Ausführen einer RP-Situation wird als "Fail RP" bezeichnet. Es ist wichtig, sich stets zu fragen, ob die Aktion, die man ausführt, realistisch für den eigenen Charakter ist. §2.0 Fahrzeugnutzung im Gebirge Fahrzeuge, die tiefergelegt sind oder offenkundig nicht für Offroad-Fahrten geeignet sind, dürfen im Gebirge nicht verwendet werden. Eine Ausnahme bilden lediglich Nutzfahrzeuge, wie Kleintransporter (z.B. Burrito, Youga, etc.), während LKW ausgeschlossen sind. §3.0 Fahrzeugnutzung mit Platten Fahrzeugnutzung mit Platten ist in bestimmten Fällen stark eingeschränkt. Wenn ein PKW zwei Platten hat, ist es nicht gestattet, weiterzufahren. In solchen Situationen sollte das Fahrzeug abgestellt und repariert werden, bevor die Fahrt fortgesetzt wird.', 117, 0, 8, 1777593600000, 'migration');
INSERT INTO laws (slug, title, category, html, text, word_count, ref_count, position, updated_at, updated_by) VALUES ('roleplay-regeln-rp-flucht', 'RP Flucht', 'Roleplay Regeln', '<h3>§1.0 · Verbot der Flucht aus Roleplay-Situationen</h3>
<p>Das Verlassen einer Roleplay-Situation durch einen Quit, Entfernen aus der Situation ist nicht erlaubt (z.B. RP Flucht).</p>
<h3>§2.0 · Das Verstecken in nicht betretbaren Gebäuden</h3>
<p>Das Verbergen in nicht für andere zugänglichen Wohnungen, Firmen oder ähnlichen Gebäuden, um einer Roleplay-Situation zu entkommen oder sich unfaire Vorteile zu verschaffen, ist untersagt.</p>', '§1.0 Verbot der Flucht aus Roleplay-Situationen Das Verlassen einer Roleplay-Situation durch einen Quit, Entfernen aus der Situation ist nicht erlaubt (z.B. RP Flucht). §2.0 Das Verstecken in nicht betretbaren Gebäuden Das Verbergen in nicht für andere zugänglichen Wohnungen, Firmen oder ähnlichen Gebäuden, um einer Roleplay-Situation zu entkommen oder sich unfaire Vorteile zu verschaffen, ist untersagt.', 55, 0, 9, 1777593600000, 'migration');
INSERT INTO laws (slug, title, category, html, text, word_count, ref_count, position, updated_at, updated_by) VALUES ('roleplay-regeln-meta-gaming', 'Meta Gaming', 'Roleplay Regeln', '<h3>§1.0 · Fairplay und Metagaming - Kein Spielwissen außerhalb des Spiels nutzen</h3>
<p>Es ist wichtig, dass du keine Informationen, die du außerhalb des Spiels erworben hast (OOC), im Spiel (IC) verwendest. Dein Charakter sollte nur über Informationen verfügen, die er innerhalb des Spiels erhalten hat.</p>
<h3>§2.0 · Keine Nutzung von Livestream-Informationen im Spiel</h3>
<p>Es ist nicht erlaubt, Informationen aus Livestreams im Spiel zu verwenden. Ebenso solltest du dich nicht am Chat- oder Streamgeschehen eines Streamers beteiligen, auch nicht, wenn der eigene Charakter in der im Stream gezeigten Situation involviert ist.</p>', '§1.0 Fairplay und Metagaming - Kein Spielwissen außerhalb des Spiels nutzen Es ist wichtig, dass du keine Informationen, die du außerhalb des Spiels erworben hast (OOC), im Spiel (IC) verwendest. Dein Charakter sollte nur über Informationen verfügen, die er innerhalb des Spiels erhalten hat. §2.0 Keine Nutzung von Livestream-Informationen im Spiel Es ist nicht erlaubt, Informationen aus Livestreams im Spiel zu verwenden. Ebenso solltest du dich nicht am Chat- oder Streamgeschehen eines Streamers beteiligen, auch nicht, wenn der eigene Charakter in der im Stream gezeigten Situation involviert ist.', 88, 0, 10, 1777593600000, 'migration');
INSERT INTO laws (slug, title, category, html, text, word_count, ref_count, position, updated_at, updated_by) VALUES ('roleplay-regeln-trolling', 'Trolling', 'Roleplay Regeln', '<h3>§1.0 · Unfairness und Belästigung im Spielumfeld</h3>
<p>Im Spielumfeld ist es wichtig, Fairness zu wahren und andere Spieler nicht zu belästigen oder das Spielerlebnis absichtlich zu stören.</p>', '§1.0 Unfairness und Belästigung im Spielumfeld Im Spielumfeld ist es wichtig, Fairness zu wahren und andere Spieler nicht zu belästigen oder das Spielerlebnis absichtlich zu stören.', 26, 0, 11, 1777593600000, 'migration');
INSERT INTO laws (slug, title, category, html, text, word_count, ref_count, position, updated_at, updated_by) VALUES ('roleplay-regeln-new-life-regel', 'New Life Regel', 'Roleplay Regeln', '<h3>§1.0 · Die New-Life Regel und die Nachsorge durch das Not-OP Team</h3>
<p>Sollte ein Mediziner vor Ort nicht verfügbar sein und du erwachst an einem nahegelegenen Ort, bedeutet dies, dass du vom Not-OP Team behandelt und nach erfolgreicher Genesung entlassen wurdest (die New-Life Regel tritt in Kraft). Du darfst dich nicht daran erinnern, wie du ohnmächtig geworden bist oder was während deiner Bewusstlosigkeit geschehen ist. Nach der Behandlung durch das Not-OP Team ist es dir nicht gestattet, zur vorherigen RP-Situation zurückzukehren.</p>
<h3>§2.0 · Erinnerung nach ärztlicher Behandlung</h3>
<p>Wenn dich ein Mediziner behandelt und wiederbelebt hat, darfst du dich an die spezielle RP-Situation erinnern.</p>
<h3>§3.0 · Fehlende Erinnerung während der Bewusstlosigkeit</h3>
<p>Während der Bewusstlosigkeit kannst du dich an keine Geschehnisse erinnern.</p>
<h3>§4.0 · Akzeptanz der Bewusstlosigkeit im Spiel</h3>
<p>Die Bewusstlosigkeit im Spiel muss, unabhängig von ihrem Grund (einschließlich Desynchronisation oder Bugs), akzeptiert und im Roleplay ausgespielt werden.</p>
<h3>§5.0 · Teilnahme an vorangegangenen RP-Situationen verboten</h3>
<p>Du darfst nicht an der vorherigen RP-Situation teilnehmen.</p>', '§1.0 Die New-Life Regel und die Nachsorge durch das Not-OP Team Sollte ein Mediziner vor Ort nicht verfügbar sein und du erwachst an einem nahegelegenen Ort, bedeutet dies, dass du vom Not-OP Team behandelt und nach erfolgreicher Genesung entlassen wurdest (die New-Life Regel tritt in Kraft). Du darfst dich nicht daran erinnern, wie du ohnmächtig geworden bist oder was während deiner Bewusstlosigkeit geschehen ist. Nach der Behandlung durch das Not-OP Team ist es dir nicht gestattet, zur vorherigen RP-Situation zurückzukehren. §2.0 Erinnerung nach ärztlicher Behandlung Wenn dich ein Mediziner behandelt und wiederbelebt hat, darfst du dich an die spezielle RP-Situation erinnern. §3.0 Fehlende Erinnerung während der Bewusstlosigkeit Während der Bewusstlosigkeit kannst du dich an keine Geschehnisse erinnern. §4.0 Akzeptanz der Bewusstlosigkeit im Spiel Die Bewusstlosigkeit im Spiel muss, unabhängig von ihrem Grund (einschließlich Desynchronisation oder Bugs), akzeptiert und im Roleplay ausgespielt werden. §5.0 Teilnahme an vorangegangenen RP-Situationen verboten Du darfst nicht an der vorherigen RP-Situation teilnehmen.', 156, 0, 12, 1777593600000, 'migration');
INSERT INTO laws (slug, title, category, html, text, word_count, ref_count, position, updated_at, updated_by) VALUES ('roleplay-regeln-schusscall', 'Schusscall', 'Roleplay Regeln', '<h3>§1.0 · Schusscall</h3>
<p>Auf Bloodline benötigt man einen Schusscall. (z.B. Hände hoch oder ich schieße). Stichwaffen sind davon ausgeschlossen.</p>
<h3>§3.0 · Dauer</h3>
<p>Ein Schusscall dauert 15 min an.</p>
<h3>§4.0 · Aufhebung im Support bei einem berechtigten Grund</h3>
<p>Es ist möglich, einen Schuss Call durch den Support aufheben zu lassen, sofern ein stichhaltiger Grund vorliegt.</p>
<h3>§5.0 · Indirekter Schusscall</h3>
<p>• Längeres Zielen auf eine Person (ca. 5 Sekunden)<br>• Bedrohungen des IC-Lebens</p>
<h3>§6.0 · Kein Grund für eine Schießerei</h3>
<p>• Beleidigungen<br>• Taser / Stanley (Pumpshotgun)</p>', '§1.0 Schusscall Auf Bloodline benötigt man einen Schusscall. (z.B. Hände hoch oder ich schieße). Stichwaffen sind davon ausgeschlossen. §3.0 Dauer Ein Schusscall dauert 15 min an. §4.0 Aufhebung im Support bei einem berechtigten Grund Es ist möglich, einen Schuss Call durch den Support aufheben zu lassen, sofern ein stichhaltiger Grund vorliegt. §5.0 Indirekter Schusscall • Längeres Zielen auf eine Person (ca. 5 Sekunden) • Bedrohungen des IC-Lebens §6.0 Kein Grund für eine Schießerei • Beleidigungen • Taser / Stanley (Pumpshotgun)', 80, 0, 13, 1777593600000, 'migration');
INSERT INTO laws (slug, title, category, html, text, word_count, ref_count, position, updated_at, updated_by) VALUES ('roleplay-regeln-reaktionszeit', 'Reaktionszeit', 'Roleplay Regeln', '<h3>§1.0 · Gib deinem Gegenüber stets ausreichend Zeit für Reaktionen</h3>
<p>Es ist wichtig sicherzustellen, dass du deinem Gegenüber immer genug Zeit gibst, um angemessen zu reagieren. ca. 5 Sekunden</p>', '§1.0 Gib deinem Gegenüber stets ausreichend Zeit für Reaktionen Es ist wichtig sicherzustellen, dass du deinem Gegenüber immer genug Zeit gibst, um angemessen zu reagieren. ca. 5 Sekunden', 28, 0, 14, 1777593600000, 'migration');
INSERT INTO laws (slug, title, category, html, text, word_count, ref_count, position, updated_at, updated_by) VALUES ('roleplay-regeln-maskierung', 'Maskierung', 'Roleplay Regeln', '<h3>§1.0 · Vollmaskierung</h3>
<p>Spieler, die eine Vollmaskierung tragen, dürfen nicht anhand ihrer Stimme oder ihres Akzents erkannt werden. Eine Vollmaskierung bedeutet das dein ganze Gesicht abgedeckt ist. Ein Bandana an sich reicht nicht!</p>
<h3>§2.0 · Einfache Masken und Identitätsverschleierung</h3>
<p>Eine einfache Maske oder Bandana, die den Mund bedeckt, wird nicht als Vollmaskierung betrachtet. Der maskierte Spieler sollte alles tun, um seine Identität zu verschleiern, einschließlich der Verwendung unauffälliger Kleidung und eines anderen Fahrzeugs.</p>
<h3>§3.0 · Identifizierung und Sichtkontakt</h3>
<p>Die Identifizierung eines Spielers kann nur durch Sichtkontakt erfolgen. Ein Spieler in einem anderen Raum wird erst als identifiziert betrachtet, wenn er gesehen wird. Im Falle von Anrufen gilt: Der Anrufer von einer unbekannten Rufnummer wird als unbekannt betrachtet. In diesem Fall sind auch Stimmverzerrer erlaubt, sofern sie in ein ordentliches RP-Hintergrund passen. Diese Regel gilt auch für Funkgeräte.</p>', '§1.0 Vollmaskierung Spieler, die eine Vollmaskierung tragen, dürfen nicht anhand ihrer Stimme oder ihres Akzents erkannt werden. Eine Vollmaskierung bedeutet das dein ganze Gesicht abgedeckt ist. Ein Bandana an sich reicht nicht! §2.0 Einfache Masken und Identitätsverschleierung Eine einfache Maske oder Bandana, die den Mund bedeckt, wird nicht als Vollmaskierung betrachtet. Der maskierte Spieler sollte alles tun, um seine Identität zu verschleiern, einschließlich der Verwendung unauffälliger Kleidung und eines anderen Fahrzeugs. §3.0 Identifizierung und Sichtkontakt Die Identifizierung eines Spielers kann nur durch Sichtkontakt erfolgen. Ein Spieler in einem anderen Raum wird erst als identifiziert betrachtet, wenn er gesehen wird. Im Falle von Anrufen gilt: Der Anrufer von einer unbekannten Rufnummer wird als unbekannt betrachtet. In diesem Fall sind auch Stimmverzerrer erlaubt, sofern sie in ein ordentliches RP-Hintergrund passen. Diese Regel gilt auch für Funkgeräte.', 134, 0, 15, 1777593600000, 'migration');
INSERT INTO laws (slug, title, category, html, text, word_count, ref_count, position, updated_at, updated_by) VALUES ('roleplay-regeln-geiselnahme-regeln', 'Geiselnahme - Regeln', 'Roleplay Regeln', '<h3>§1.0 · Priorität des RP bei Geiselnahmen</h3>
<p>Bei einer Geiselnahme sollte das Rollenspiel (RP) immer im Vordergrund stehen, und nicht das Lösegeld oder Equipment.</p>
<h3>§2.0 · Unabhängige Geiselnahmen durch Gruppierungen</h3>
<p>Gruppierungen müssen eine Geiselnahme ohne Unterstützung von anderen Parteien durchführen.</p>
<h3>§3.0 · Lösegeld für Zivilisten/Beamten</h3>
<p>Es darf maximal 5.000$ gefordert werden aber im Vordergrund steht das RP. Z.B Es wird 20.000$ gefordert so verhandelt mit der Person und sagt nicht gleich ist nicht erlaubt!</p>', '§1.0 Priorität des RP bei Geiselnahmen Bei einer Geiselnahme sollte das Rollenspiel (RP) immer im Vordergrund stehen, und nicht das Lösegeld oder Equipment. §2.0 Unabhängige Geiselnahmen durch Gruppierungen Gruppierungen müssen eine Geiselnahme ohne Unterstützung von anderen Parteien durchführen. §3.0 Lösegeld für Zivilisten/Beamten Es darf maximal 5.000$ gefordert werden aber im Vordergrund steht das RP. Z.B Es wird 20.000$ gefordert so verhandelt mit der Person und sagt nicht gleich ist nicht erlaubt!', 71, 0, 16, 1777593600000, 'migration');
INSERT INTO laws (slug, title, category, html, text, word_count, ref_count, position, updated_at, updated_by) VALUES ('roleplay-regeln-durchsuchen-abnehmen', 'Durchsuchen / Abnehmen', 'Roleplay Regeln', '<h3>§1.0 · Staatswaffen</h3>
<p>Vom SWAT oder allgemein Staatlichen Fraktionen dürfen gewisse Items nicht abgenommen werden:<br>• Einsatzschild<br>• jegdliche Art von Waffen</p>
<h3>§2.0 · Verboten Items</h3>
<p>Es gibt gewisse Gegenstände die du nicht abnehmen darfst:<br>• Angeln<br>• Rucksack</p>
<h3>§3.0 · Abnehmen/Geld</h3>
<p>Es darf alles bis auf das oben genannte abgenommen werden. Es darf max. 5k Grüngeld abgenommen werden.</p>', '§1.0 Staatswaffen Vom SWAT oder allgemein Staatlichen Fraktionen dürfen gewisse Items nicht abgenommen werden: • Einsatzschild • jegdliche Art von Waffen §2.0 Verboten Items Es gibt gewisse Gegenstände die du nicht abnehmen darfst: • Angeln • Rucksack §3.0 Abnehmen/Geld Es darf alles bis auf das oben genannte abgenommen werden. Es darf max. 5k Grüngeld abgenommen werden.', 56, 0, 17, 1777593600000, 'migration');
INSERT INTO laws (slug, title, category, html, text, word_count, ref_count, position, updated_at, updated_by) VALUES ('fraktionsregelwerk-fraktionsregeln', 'Fraktionsregeln', 'Fraktionsregelwerk', '<h3>§1.0 · Mitgliederregelung</h3>
<p>Maximal 20 Mitglieder pro Fraktion + 2 Frauenplätze</p>
<h3>§1.1 · Blood Out</h3>
<p>Bei einem Blood Out vergisst du alle Infos, die du durch deine Fraktion gewonnen hast. Fraktionsperre: 3 Tage</p>
<h3>§1.2 · Erkennungsmerkmale</h3>
<p>Mitglieder illegaler Fraktionen müssen durch zwei klar erkennbare Merkmale identifizierbar sein</p>
<h3>§1.3 · Fahrzeugvorschriften</h3>
<p>Fraktionsfahrzeuge müssen eindeutig gekennzeichnet sein (nur aus Fraktionsgaragen). Private Fahrzeuge für Fraktionsaktivitäten sind nicht gestattet</p>
<h3>§1.4 · Drittpartei</h3>
<p>Die Einmischung einer dritten Partei ist untersagt</p>
<h3>§1.5 · Baseraid</h3>
<p>Pro Server-Restart ein Baseraid. Keine Angriffe 30 Minuten vor oder nach Neustarts. Das Abcampen von GW-Punkten ist verboten. Unbefugtes Betreten eines Anwesens/einer Hood wird als Baseraid gewertet</p>
<h3>§1.6 · Sicario</h3>
<p>48-stündige Sperre nach Austritt. Rückkehr zur Ursprungsfraktion nach 1 Monat möglich. Eine Sicario muss beim Frakverwaltung angefragt werden. Bis zu 10% des Lagers dürfen entnommen werden</p>
<h3>§1.7 · Stürzen</h3>
<p>Beim Stürzen muss 80% der Familie hinter dir stehen (4 Leute dürfen maximal dagegenstimmen). Ein Stürzen des Leaders muss bei der Frakverwaltung angefragt werden.</p>
<h3>§1.8 · Konflikteinleitung</h3>
<p>Zwei vorherige Verhandlungen mit der gegnerischen Führung notwendig. Konkrete Forderungen müssen klar kommuniziert werden</p>
<h3>§1.9 · Konfliktprotokollierung</h3>
<p>Konfliktgründe sind unverzüglich im Fraktions-Discord zu dokumentieren. Für einen Konflikt sind Konflikt Clips nötig</p>
<h3>§1.10 · Forderungen</h3>
<p>Die Maximalforderung ohne Kriegsvertrag beträgt 50.000€. Die Maximalforderung mit Kriegsvertrag beträgt 100.000€</p>
<h3>§1.11 · Verbot von Söldnern</h3>
<p>Leute, die nur fürs Schießen kommen, werden aussortiert, und die Fraktion wird ebenfalls sanktioniert. Bei Verstößen: Fraktionsverwarnung</p>
<h3>§1.12 · Routen</h3>
<p>Jede Fraktion darf nur eine Route besitzen. Unterlegene Fraktion: 10-tägige Wartefrist für erneuten Anspruch</p>
<h3>§1.13 · Routenkrieg</h3>
<p>Anspruch durch Forderung bei der Fraktion. Kriegsvertrag muss innerhalb von 48 Stunden bei der Fraktionsverwaltung eingereicht werden</p>
<h3>§1.14 · Konfliktabschluss</h3>
<p>Wenn die Fraktion auszahlt, ist der Krieg offiziell vorbei</p>
<h3>§1.15 · Zahlungsmodalitäten</h3>
<p>Forderungen sind persönlich zwischen den 12ern zu begleichen</p>
<h3>§2.0 · First-Contact-Regel</h3>
<p>Bei Kampfbeginn müssen alle innerhalb von 10 Sekunden Fahrzeuge verlassen. Backstep muss 5 Minuten nach First Contact aussteigen. Erlaubtes Fahrzeuge: Komoda. Verstoß: Automatische Niederlage</p>
<h3>§2.1 · Lagerverwaltung</h3>
<p>Plünderung des Fraktionslagers untersagt (Ausnahme: §1.6). Private Vorräte sind nicht gestattet</p>
<h3>§2.2 · Trash-Talk</h3>
<p>Nur Rang 11/12 dürfen nach Kämpfen verbale Provokationen äußern. Unterlegene müssen sich der siegreichen Fraktion unterordnen</p>
<h3>§2.3 · Korruptionsbestimmungen</h3>
<p>DOJ & Regierung: Informationsweitergabe erlaubt. LSPD (bis Rang 10): Informationsweitergabe erlaubt. LSMD: Nur Informationsweitergabe erlaubt</p>
<h3>§2.4 · Razzia</h3>
<p>Einzelne Straftaten dürfen nicht als Razzia-Grund dienen</p>', '§1.0 Mitgliederregelung Maximal 20 Mitglieder pro Fraktion + 2 Frauenplätze §1.1 Blood Out Bei einem Blood Out vergisst du alle Infos, die du durch deine Fraktion gewonnen hast. Fraktionsperre: 3 Tage §1.2 Erkennungsmerkmale Mitglieder illegaler Fraktionen müssen durch zwei klar erkennbare Merkmale identifizierbar sein §1.3 Fahrzeugvorschriften Fraktionsfahrzeuge müssen eindeutig gekennzeichnet sein (nur aus Fraktionsgaragen). Private Fahrzeuge für Fraktionsaktivitäten sind nicht gestattet §1.4 Drittpartei Die Einmischung einer dritten Partei ist untersagt §1.5 Baseraid Pro Server-Restart ein Baseraid. Keine Angriffe 30 Minuten vor oder nach Neustarts. Das Abcampen von GW-Punkten ist verboten. Unbefugtes Betreten eines Anwesens/einer Hood wird als Baseraid gewertet §1.6 Sicario 48-stündige Sperre nach Austritt. Rückkehr zur Ursprungsfraktion nach 1 Monat möglich. Eine Sicario muss beim Frakverwaltung angefragt werden. Bis zu 10% des Lagers dürfen entnommen werden §1.7 Stürzen Beim Stürzen muss 80% der Familie hinter dir stehen (4 Leute dürfen maximal dagegenstimmen). Ein Stürzen des Leaders muss bei der Frakverwaltung angefragt werden. §1.8 Konflikteinleitung Zwei vorherige Verhandlungen mit der gegnerischen Führung notwendig. Konkrete Forderungen müssen klar kommuniziert werden §1.9 Konfliktprotokollierung Konfliktgründe sind unverzüglich im Fraktions-Discord zu dokumentieren. Für einen Konflikt sind Konflikt Clips nötig §1.10 Forderungen Die Maximalforderung ohne Kriegsvertrag beträgt 50.000€. Die Maximalforderung mit Kriegsvertrag beträgt 100.000€ §1.11 Verbot von Söldnern Leute, die nur fürs Schießen kommen, werden aussortiert, und die Fraktion wird ebenfalls sanktioniert. Bei Verstößen: Fraktionsverwarnung §1.12 Routen Jede Fraktion darf nur eine Route besitzen. Unterlegene Fraktion: 10-tägige Wartefrist für erneuten Anspruch §1.13 Routenkrieg Anspruch durch Forderung bei der Fraktion. Kriegsvertrag muss innerhalb von 48 Stunden bei der Fraktionsverwaltung eingereicht werden §1.14 Konfliktabschluss Wenn die Fraktion auszahlt, ist der Krieg offiziell vorbei §1.15 Zahlungsmodalitäten Forderungen sind persönlich zwischen den 12ern zu begleichen §2.0 First-Contact-Regel Bei Kampfbeginn müssen alle innerhalb von 10 Sekunden Fahrzeuge verlassen. Backstep muss 5 Minuten nach First Contact aussteigen. Erlaubtes Fahrzeuge: Komoda. Verstoß: Automatische Niederlage §2.1 Lagerverwaltung Plünderung des Fraktionslagers untersagt (Ausnahme: §1.6). Private Vorräte sind nicht gestattet §2.2 Trash-Talk Nur Rang 11/12 dürfen nach Kämpfen verbale Provokationen äußern. Unterlegene müssen sich der siegreichen Fraktion unterordnen §2.3 Korruptionsbestimmungen DOJ & Regierung: Informationsweitergabe erlaubt. LSPD (bis Rang 10): Informationsweitergabe erlaubt. LSMD: Nur Informationsweitergabe erlaubt §2.4 Razzia Einzelne Straftaten dürfen nicht als Razzia-Grund dienen', 359, 0, 18, 1777593600000, 'migration');
INSERT INTO laws (slug, title, category, html, text, word_count, ref_count, position, updated_at, updated_by) VALUES ('fraktionsregelwerk-routen-regeln', 'Routen Regeln', 'Fraktionsregelwerk', '<h3>§1.0 · Legale und Illegale Routen</h3>
<p>Es gibt legale und illegale Routen. Legale Routen dürfen nicht eingenommen werden, während illegale Routen eingenommen werden können.</p>
<h3>§2.0 · Legale Routen</h3>
<p>• Westen<br>• Tabak<br>• Apfel<br>• Metallplatten</p>
<h3>§3.0 · Illegale Routen</h3>
<p>• Waffenroute<br>• Metall<br>• Munition<br>• Weed<br>• Kokain</p>
<h3>§4.0 · Routen Razzia</h3>
<p>Auf jeder illegalen Route kann alle 24 Stunden eine Razzia durchgeführt werden. Bei einer Razzia werden alle auf der Route befindlichen Waren konfisziert.<br><br><strong>Verteidigung der Route:</strong> Eine Route darf nur von den rechtmäßigen Besitzern und denjenigen verteidigt werden, die sich aktuell auf der Route befinden. Dies bedeutet, dass nur die Mitglieder der Gruppierung, die sich zum Zeitpunkt der Razzia auf der Route befinden, aktiv an der Verteidigung teilnehmen dürfen.</p>', '§1.0 Legale und Illegale Routen Es gibt legale und illegale Routen. Legale Routen dürfen nicht eingenommen werden, während illegale Routen eingenommen werden können. §2.0 Legale Routen • Westen • Tabak • Apfel • Metallplatten §3.0 Illegale Routen • Waffenroute • Metall • Munition • Weed • Kokain §4.0 Routen Razzia Auf jeder illegalen Route kann alle 24 Stunden eine Razzia durchgeführt werden. Bei einer Razzia werden alle auf der Route befindlichen Waren konfisziert. Verteidigung der Route: Eine Route darf nur von den rechtmäßigen Besitzern und denjenigen verteidigt werden, die sich aktuell auf der Route befinden. Dies bedeutet, dass nur die Mitglieder der Gruppierung, die sich zum Zeitpunkt der Razzia auf der Route befinden, aktiv an der Verteidigung teilnehmen dürfen.', 119, 0, 19, 1777593600000, 'migration');
INSERT INTO laws (slug, title, category, html, text, word_count, ref_count, position, updated_at, updated_by) VALUES ('fraktionsregelwerk-banden-regeln', 'Banden Regeln', 'Fraktionsregelwerk', '<h3>§1.0 · Banden und ihre Merkmale</h3>
<p>Banden sind informelle Gruppierungen, die nicht offiziell angemeldet sind. Sie bestehen aus höchstens 6 Zivilisten, die gemeinsam kriminelle Aktivitäten ausüben. Sie brauchen mindestens 3 gleiche Erkennungsmerkmale.</p>
<h3>§2.0 · Mitgliederbegrenzung</h3>
<p>Die Höchstgrenze von 6 Personen darf nicht überschritten werden.</p>
<h3>§3.0 · Interaktion mit angemeldeten Gruppierungen</h3>
<p>Banden sollten sich in laufenden Situationen von angemeldeten Gruppierungen fernhalten.</p>
<h3>§4.0 · Kontinuität in RP-Strängen</h3>
<p>Innerhalb eines Zeitraums von 24 Stunden sollten die Spieler in einem RP-Strang keine gravierenden Veränderungen vornehmen.</p>', '§1.0 Banden und ihre Merkmale Banden sind informelle Gruppierungen, die nicht offiziell angemeldet sind. Sie bestehen aus höchstens 6 Zivilisten, die gemeinsam kriminelle Aktivitäten ausüben. Sie brauchen mindestens 3 gleiche Erkennungsmerkmale. §2.0 Mitgliederbegrenzung Die Höchstgrenze von 6 Personen darf nicht überschritten werden. §3.0 Interaktion mit angemeldeten Gruppierungen Banden sollten sich in laufenden Situationen von angemeldeten Gruppierungen fernhalten. §4.0 Kontinuität in RP-Strängen Innerhalb eines Zeitraums von 24 Stunden sollten die Spieler in einem RP-Strang keine gravierenden Veränderungen vornehmen.', 77, 0, 20, 1777593600000, 'migration');
INSERT INTO laws (slug, title, category, html, text, word_count, ref_count, position, updated_at, updated_by) VALUES ('fraktionsregelwerk-gangwar-regeln', 'Gangwar Regeln', 'Fraktionsregelwerk', '<h3>§1.0 · First Contact</h3>
<p>Der Masse steigt bei den ersten Kontakt zu der gegen Partei aus. Der Backstep hat dann noch 5 Minuten Zeit bis er selbst aussteigen muss!</p>
<h3>§2.0 · OOC Zone</h3>
<p>Alles was in Gangwar passiert bleibt in Gangwar. Es dürfen deswegen keine Kriege/Fights entstehen.</p>', '§1.0 First Contact Der Masse steigt bei den ersten Kontakt zu der gegen Partei aus. Der Backstep hat dann noch 5 Minuten Zeit bis er selbst aussteigen muss! §2.0 OOC Zone Alles was in Gangwar passiert bleibt in Gangwar. Es dürfen deswegen keine Kriege/Fights entstehen.', 45, 0, 21, 1777593600000, 'migration');
